/// <summary>
/// PricingAttribute of table <c>RetailSalesTable</c> field CreditCardTypeId.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::SalesTable, UPSPricingAttributeSourceLevel::Header)]
class UPSPricingAttributeRetailSalesTableCreditCardTypeId extends UPSPricingAttributeRetailSalesTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(RetailSalesTable, CreditCardTypeId);
}

public Set getAllowedValues()
{
    RetailSalesTable    retailSalesTable;
    var                 ret = new Set(Types::String);

    while select CreditCardTypeId from retailSalesTable
        group by CreditCardTypeId
    {
        ret.add(retailSalesTable.StatementId);
    }

    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(RetailSalesTable, CreditCardTypeId));
    qbr.value(queryValue(_value));
}
